        BVHIntersect(nodes, triangles, ray);

        int offset = y * width + x;
        image[offset] = ray.maxt;
        id[offset] = ray.hitId;
    }
}

static void raytrace_openmp(int width, int height, int baseWidth, int baseHeight,
                            const float raster2camera[4][4], const float camera2world[4][4],
                            float image[], int id[], const LinearBVHNode nodes[],
                            const Triangle triangles[], int threads) {
    if (width <= 0 || height <= 0)
        return;

    const int teamSize = std::min(threads, height);
    if (teamSize <= 1) {
        raytrace_serial(width, height, baseWidth, baseHeight, raster2camera, camera2world,
                       image, id, nodes, triangles);
        return;
    }

    const float widthScale = float(baseWidth) / float(width);
    const float heightScale = float(baseHeight) / float(height);

    if (teamSize <= 4) {
        // Static row ownership avoids per-row dispatch for small teams.
        #pragma omp parallel for schedule(static) num_threads(teamSize)
        for (int y = 0; y < height; ++y) {
            raytrace_row(y, width, widthScale, heightScale, raster2camera, camera2world,
                         image, id, nodes, triangles);
        }
    } else {
        // Dynamic row assignment can balance variation in BVH work at larger teams.
        #pragma omp parallel for schedule(dynamic, 1) num_threads(teamSize)
        for (int y = 0; y < height; ++y) {
            raytrace_row(y, width, widthScale, heightScale, raster2camera, camera2world,
                         image, id, nodes, triangles);
        }
    }
}

